let velocidad = 0.01;

let arriba = false;
let abajo = false;
let izquierda = false;
let derecha = false;

let mora = scene.getObjectByName("Mora");
let moraEjecutada = false;
let fresa = scene.getObjectByName("Fresa");
let fresaEjecutada = false;
let uva = scene.getObjectByName("Uva");
let uvaEjecutada = false;
let arandano = scene.getObjectByName("Arandano");
let arandanoEjecutada = false;

const audio = player.loadAudio('oso', 'https://bearry.vercel.app/assets/audio/Zmusic.mp3', (audio) => {
    audio.setLoop(false);
    audio.setVolume(0.5);
    audio.play();
});

function collect(){
	const audio2 = player.loadAudio('fruta', 'https://bearry.vercel.app/assets/audio/collectpin.mp3', (audio2) => {
    audio2.setLoop(false);
    audio2.setVolume(2);
    audio2.play();
	});
}



document.addEventListener("keydown", function(event) {
    if (event.key === "ArrowUp") arriba = true;
    if (event.key === "ArrowDown") abajo = true;
    if (event.key === "ArrowLeft") izquierda = true;
    if (event.key === "ArrowRight") derecha = true;
});

document.addEventListener("keyup", function(event) {
    if (event.key === "ArrowUp") arriba = false;
    if (event.key === "ArrowDown") abajo = false;
    if (event.key === "ArrowLeft") izquierda = false;
    if (event.key === "ArrowRight") derecha = false;
});

function update(event) {
    if (arriba && this.position.z > -1.0) {
        this.position.z -= velocidad;
        this.rotation.z = -Math.PI;
    }

    if (abajo && this.position.z < 1.0) {
        this.position.z += velocidad;
        this.rotation.z = 0;
    }

    if (izquierda && this.position.x > -0.8) {
        this.position.x -= velocidad;
        this.rotation.z = Math.PI / 2;
    }

    if (derecha && this.position.x < 0.8) {
        this.position.x += velocidad;
        this.rotation.z = -Math.PI / 2;
    }



	if (Math.abs(this.position.x - 0.4) < 0.08 && Math.abs(this.position.z - (-0.2)) < 0.08 && !moraEjecutada) {
		mora.visible = false;
		Mora();
		moraEjecutada = true;
		collect();
	}

	if (Math.abs(this.position.x - 0.03) < 0.08 && Math.abs(this.position.z - 0.8) < 0.08 && !fresaEjecutada) {
		fresa.visible = false;
		Fresa();
		fresaEjecutada = true;
		collect();
	}

	if (Math.abs(this.position.x - (-0.5)) < 0.08 && Math.abs(this.position.z - 0.05) < 0.08 && !uvaEjecutada) {
		uva.visible = false;
		Uva();
		uvaEjecutada = true;
		collect();
	}

	if (Math.abs(this.position.x - 0.42) < 0.08 && Math.abs(this.position.z - 0.25) < 0.08 && !arandanoEjecutada) {
		arandano.visible = false;
		Arandano();
		arandanoEjecutada = true;
		collect();

	}


}

